import queue

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Create a bounded queue of capacity `cap` and try to put each element

    from `xs` without blocking. Count how many elements were accepted
    before the queue became full, then stop.
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
            count += 1
        except queue.Full:
            break
    return count


def test_accepted_fewer_than_capacity() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_accepted_exceeds_capacity() -> None:
    assert accepted(2, [10, 20, 30, 40]) == 2


def test_accepted_exact_capacity() -> None:
    assert accepted(3, [1, 2, 3]) == 3


def test_accepted_empty_list() -> None:
    assert accepted(3, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_single_capacity() -> None:
    assert accepted(1, [42]) == 1
    assert accepted(1, [42, 43]) == 1

